"""In-process unit tests for wordstat.cli pure functions (T1).

Subprocess/byte-level coverage lives in the T2/T3 suites; these tests import
wordstat.cli directly. Where a test proves an acceptance criterion, the AC id
is cited (AC5 tie order, AC6 empty file, AC13 --top validation, AC21 unit
counting/tokenisation edges).
"""

import argparse

import pytest

from wordstat.cli import build_parser, count, format_json, format_text

SAMPLE = "The cat sat.\nThe cat ran!\nA dog.\n"


# --- build_parser -----------------------------------------------------------

def test_parser_prog_is_wordstat():
    assert build_parser().prog == "wordstat"


def test_parser_defaults():
    args = build_parser().parse_args(["f.txt"])
    assert args.json is False
    assert args.top == 3
    assert args.file == "f.txt"


def test_parser_json_flag_sets_true():
    assert build_parser().parse_args(["--json", "f.txt"]).json is True


def test_parser_single_positional_file():
    assert build_parser().parse_args(["only.txt"]).file == "only.txt"


@pytest.mark.parametrize("bad", ["0", "-1", "abc"])
def test_parser_rejects_bad_top_AC13(bad, capsys):
    parser = build_parser()
    with pytest.raises(SystemExit) as exc_info:
        parser.parse_args(["--top", bad, "f.txt"])
    assert exc_info.value.code == 2
    assert "wordstat: error: " in capsys.readouterr().err


def test_parser_accepts_top_one():
    assert build_parser().parse_args(["--top", "1", "f.txt"]).top == 1


# --- count ------------------------------------------------------------------

def test_count_contract_example_AC21():
    """Contract worked example: 3/8/33, top cat=2 the=2 a=1."""
    result = count(SAMPLE, 3)
    assert result == {
        "lines": 3,
        "words": 8,
        "chars": 33,
        "top": [("cat", 2), ("the", 2), ("a", 1)],
    }


def test_count_top2_truncates():
    assert count(SAMPLE, 2)["top"] == [("cat", 2), ("the", 2)]


def test_count_empty_string_AC6():
    result = count("", 3)
    assert result == {"lines": 0, "words": 0, "chars": 0, "top": []}


def test_count_punctuation_only_words_zero():
    result = count("!!! ... ???\n\n", 3)
    assert result["words"] == 0
    assert result["top"] == []
    assert result["lines"] == 2


def test_count_ties_ordered_by_count_desc_then_word_asc_AC5():
    # most_common would give b,a,c (first-seen); D7 requires a,c after b.
    result = count("b b a c", 10)
    assert result["top"] == [("b", 2), ("a", 1), ("c", 1)]


def test_count_fewer_distinct_words_than_n_lists_all():
    assert count("a b", 5)["top"] == [("a", 1), ("b", 1)]


def test_count_cafe_token_is_ascii_prefix_AC21():
    # é is not [a-z0-9]; "café" -> single token "caf".
    result = count("café", 10)
    assert result["words"] == 1
    assert result["top"] == [("caf", 1)]
    assert result["chars"] == 4


def test_count_istanbul_lowercases_to_two_tokens_AC21():
    # "İ".lower() is two code points (i + U+0307) -> tokens "i", "stanbul";
    # proves re.IGNORECASE is NOT used (it would match the whole word).
    result = count("İstanbul", 10)
    assert result["words"] == 2
    assert result["top"] == [("i", 1), ("stanbul", 1)]


def test_count_astral_emoji_is_one_char():
    result = count("\U0001f600", 3)
    assert result["chars"] == 1
    assert result["words"] == 0


def test_count_crlf_counts_cr_in_chars_but_collapses_lines():
    # D1 semantics: text arrives already decoded with no newline translation.
    result = count("a\r\nb", 3)
    assert result == {
        "lines": 2,
        "words": 2,
        "chars": 4,
        "top": [("a", 1), ("b", 1)],
    }


# --- format_text ------------------------------------------------------------

def test_format_text_contract_example_byte_exact():
    assert format_text(count(SAMPLE, 3)) == (
        "lines: 3\nwords: 8\nchars: 33\ntop: cat=2 the=2 a=1\n"
    )


def test_format_text_empty_top_no_trailing_space_AC6_D5():
    assert format_text(count("", 3)) == "lines: 0\nwords: 0\nchars: 0\ntop:\n"


# --- format_json ------------------------------------------------------------

def test_format_json_contract_example_top2_byte_exact():
    assert format_json(count(SAMPLE, 2)) == (
        '{"lines": 3, "words": 8, "chars": 33, '
        '"top": [{"word": "cat", "count": 2}, {"word": "the", "count": 2}]}\n'
    )


def test_format_json_empty_top_AC6():
    assert format_json(count("", 3)) == (
        '{"lines": 0, "words": 0, "chars": 0, "top": []}\n'
    )
